WITH base AS (SELECT id, full_name, email, dept_id, manager_id, job_title, salary, hire_date, level, ROUND(salary, 2) AS salary_rounded, ROUND(salary * 100, 2) AS salary_adjusted, COALESCE(level, 'UNKNOWN') AS level_clean FROM employees WHERE hire_date >= TO_DATE('2023-03-15') AND job_title IS DISTINCT FROM 'Designer') SELECT * FROM (SELECT manager_id, job_title, salary FROM base) src PIVOT (AVG(salary) AS total, COUNT(1) AS cnt FOR job_title IN ('Engineer' AS engineer, 'Analyst' AS analyst, 'Designer' AS designer));
